package tokenizer

import java.time.{LocalDate, LocalDateTime}
import java.time.format.DateTimeFormatter
import scala.collection.mutable
import io.circe.Json

/**
 * Tokenizer module for converting various input types to standardized string tokens.
 * Translated from Python to Scala 2.13.
 */

// ============================================================================
// Enums and Constants
// ============================================================================

sealed trait TokenType {
  def value: String
}

object TokenType {
  case object STRING extends TokenType { val value = "string" }
  case object NUMERIC extends TokenType { val value = "numeric" }
  case object TEMPORAL extends TokenType { val value = "temporal" }
  case object STRUCTURED extends TokenType { val value = "structured" }
  case object BINARY extends TokenType { val value = "binary" }
  case object NULL extends TokenType { val value = "null" }
}

// ============================================================================
// Core Token Classes
// ============================================================================

/**
 * Immutable token representation.
 */
case class Token(
    value: String,
    tokenType: TokenType,
    metadata: Map[String, Any] = Map.empty
) {
  /**
   * Return new token with additional metadata.
   */
  def withMetadata(kwargs: (String, Any)*): Token = {
    copy(metadata = metadata ++ kwargs.toMap)
  }
}

/**
 * Mutable batch of tokens - contrast with immutable Token.
 */
class MutableTokenBatch {
  private val _tokens = mutable.ListBuffer.empty[Token]
  private var _processed = false

  def tokens: List[Token] = _tokens.toList

  def add(token: Token): Unit = {
    if (_processed) throw new RuntimeException("Batch already processed")
    _tokens += token
  }

  def markProcessed(): Unit = {
    _processed = true
  }
}

// ============================================================================
// Protocols (Traits)
// ============================================================================

/**
 * Any object that can be converted to a token string.
 */
trait Tokenizable {
  def toToken: String
}

// ============================================================================
// Generic Container Classes
// ============================================================================

/**
 * Covariant container - can return subtypes.
 */
class TokenContainer[+T](private val items: Seq[T]) {
  def getAll: Seq[T] = items
  def size: Int = items.size
  def mapTokens(func: T => String): List[String] = items.map(func).toList
}

/**
 * Contravariant sink - can accept supertypes.
 */
class TokenSink[-T] {
  private val _received = mutable.ListBuffer.empty[Any]

  def receive(item: T): Unit = {
    _received += item
  }

  def drain(): List[Any] = {
    val result = _received.toList
    _received.clear()
    result
  }
}

/**
 * Invariant handler - exact type matching required.
 */
class BivariantHandler[T](private var value: T) {
  def get: T = value
  def set(newValue: T): Unit = {
    value = newValue
  }
  def transform(func: T => T): T = {
    value = func(value)
    value
  }
}

// ============================================================================
// Tokenizer Implementations
// ============================================================================

/**
 * Abstract base tokenizer with generic input type.
 */
trait BaseTokenizer[T] {
  /**
   * Convert value to token.
   */
  def tokenize(value: T): Token

  /**
   * Lazy tokenization of multiple values.
   */
  def tokenizeBatch(values: Iterable[T]): Iterator[Token] = {
    values.iterator.map(tokenize)
  }
}

/**
 * Tokenizer for string and bytes types.
 */
class StringTokenizer(
    val encoding: String = "UTF-8",
    val normalizer: String => String = identity
) extends BaseTokenizer[Either[String, Array[Byte]]] {

  override def tokenize(value: Either[String, Array[Byte]]): Token = {
    val strValue = value match {
      case Left(s) => s
      case Right(b) => new String(b, encoding)
    }
    Token(normalizer(strValue), TokenType.STRING)
  }

  def tokenize(value: String): Token = tokenize(Left(value))
  def tokenize(value: Array[Byte]): Token = tokenize(Right(value))
}

/**
 * Tokenizer for numeric types with precision handling.
 */
class NumericTokenizer(
    val precision: Int = 6,
    val formatOptions: Map[String, Any] = Map.empty
) extends BaseTokenizer[BigDecimal] {

  override def tokenize(value: BigDecimal): Token = {
    val strValue = s"%.${precision}f".format(value)
    Token(strValue, TokenType.NUMERIC, Map("original_type" -> value.getClass.getSimpleName))
  }
}

/**
 * Tokenizer for date/time types.
 */
class TemporalTokenizer(
    val formatStr: Option[String] = None
) extends BaseTokenizer[Either[LocalDateTime, LocalDate]] {

  private val ISO_FORMAT = DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm:ss")
  private val DATE_FORMAT = DateTimeFormatter.ISO_LOCAL_DATE

  override def tokenize(value: Either[LocalDateTime, LocalDate]): Token = {
    val formatter = formatStr.map(DateTimeFormatter.ofPattern).getOrElse {
      value match {
        case Left(_) => ISO_FORMAT
        case Right(_) => DATE_FORMAT
      }
    }

    val strValue = value match {
      case Left(dt) => dt.format(formatter)
      case Right(d) => d.format(formatter)
    }

    Token(strValue, TokenType.TEMPORAL)
  }

  def tokenize(dt: LocalDateTime): Token = tokenize(Left(dt))
  def tokenize(d: LocalDate): Token = tokenize(Right(d))
}

/**
 * Tokenizer that handles multiple types with overloaded methods.
 */
class UniversalTokenizer {
  private val stringTokenizer = new StringTokenizer()
  private val numericTokenizer = new NumericTokenizer()
  private val temporalTokenizer = new TemporalTokenizer()

  def tokenizeNull: Token = Token("NULL", TokenType.NULL)

  /**
   * Dispatch to appropriate tokenizer based on runtime type.
   */
  def tokenize(value: Any): Token = value match {
    case null => tokenizeNull
    case t: Tokenizable => Token(t.toToken, TokenType.STRUCTURED)
    case s: String => stringTokenizer.tokenize(s)
    case b: Array[Byte] => stringTokenizer.tokenize(b)
    case i: Int => numericTokenizer.tokenize(BigDecimal(i))
    case l: Long => numericTokenizer.tokenize(BigDecimal(l))
    case f: Float => numericTokenizer.tokenize(BigDecimal(f.toDouble))
    case d: Double => numericTokenizer.tokenize(BigDecimal(d))
    case bd: BigDecimal => numericTokenizer.tokenize(bd)
    case dt: LocalDateTime => temporalTokenizer.tokenize(dt)
    case d: LocalDate => temporalTokenizer.tokenize(d)
    case other => Token(other.toString, TokenType.STRING, Map("fallback" -> true))
  }
}

